		b := &rep.Buckets[index[bucketStart(day, g).Format(time.DateOnly)]]
		b.Amounts[k.cur] += t.amount
		b.Payments += t.payments
	}
	return rep, nil
}

// dayCurrency is one day and currency of a report.
type dayCurrency struct {
	day string
	cur money.Currency
}

// total is what the payments of one day and currency add up to.
type total struct {
	amount   int64
	payments int
}

// sumDays adds up the succeeded payments per day, in loc, and currency from start to last, both included.
func sumDays(st *store.Store, orgID string, loc *time.Location, start, last time.Time) map[dayCurrency]total {
	from, to := start.Format(time.DateOnly), last.Format(time.DateOnly)
	sums := map[dayCurrency]total{}
	for _, p := range st.Payments(orgID, "") {
		day := p.CreatedAt.In(loc).Format(time.DateOnly)
		if p.Status != store.PaymentSucceeded || day < from || day > to {
			continue
		}
		k := dayCurrency{day, p.Currency}
		t := sums[k]
		t.amount += p.Amount
		t.payments++
		sums[k] = t
	}
	return sums
}

// parseRange reads the days from and to, both included, which must be valid and at most MaxDays apart.
func parseRange(from, to string) (time.Time, time.Time, error) {
	start, err := time.Parse(time.DateOnly, from)
	if err != nil {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: from %q", ErrInvalidDate, from)
	}
	last, err := time.Parse(time.DateOnly, to)
	if err != nil {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: to %q", ErrInvalidDate, to)
	}
	if last.Before(start) {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: to is before from", ErrInvalidRange)
	}
	if last.Sub(start) >= MaxDays*24*time.Hour {
		return time.Time{}, time.Time{}, fmt.Errorf("%w: at most %d days", ErrInvalidRange, MaxDays)
	}
	return start, last, nil
}

// orgLocation returns the name and location of an organization's time zone. An organization that does not exist has no
// payments, so it is reported in UTC.
func orgLocation(st *store.Store, orgID string) (string, *time.Location) {
	org, ok := st.Org(orgID)
	if !ok {
		return "UTC", time.UTC
	}
	loc, err := time.LoadLocation(org.TimeZone)
	if err != nil {
		return "UTC", time.UTC
	}
	return org.TimeZone, loc
}

// bucketStart is the first day of the group's bucket that day d (a calendar day, in UTC) is in.
func bucketStart(d time.Time, g Group) time.Time {
	switch g {
	case GroupWeek:
		return d.AddDate(0, 0, -(int(d.Weekday()) + 6) % 7)
	case GroupMonth:
		return time.Date(d.Year(), d.Month(), 1, 0, 0, 0, 0, time.UTC)
	}
	return d
}

// nextBucket is the bucket after the one starting on b.
func nextBucket(b time.Time, g Group) time.Time {
	switch g {
	case GroupWeek:
		return b.AddDate(0, 0, 7)
	case GroupMonth:
		return b.AddDate(0, 1, 0)
	}
	return b.AddDate(0, 0, 1)
}

